/* Original C definitions used by the independent integer compatibility oracle. */
#include <stdio.h>

#define COMP_ID(x) (x)
#define COMP_ADD(a, b) ((a) + (b))
#define COMP_SUB(a, b) ((a) - (b))
#define COMP_MUL(a, b) ((a) * (b))
#define COMP_DIV(a, b) ((a) / (b))
#define COMP_REM(a, b) ((a) % (b))
#define COMP_AND_BITS(a, b) ((a) & (b))
#define COMP_OR_BITS(a, b) ((a) | (b))
#define COMP_XOR_BITS(a, b) ((a) ^ (b))
#define COMP_NOT_BITS(x) (~(x))
#define COMP_NEG(x) (-(x))
#define COMP_PLUS(x) (+(x))
#define COMP_EQ(a, b) ((a) == (b))
#define COMP_NE(a, b) ((a) != (b))
#define COMP_LT(a, b) ((a) < (b))
#define COMP_LE(a, b) ((a) <= (b))
#define COMP_GT(a, b) ((a) > (b))
#define COMP_GE(a, b) ((a) >= (b))
#define COMP_NOT(x) (!(x))
#define COMP_SHL(a, b) ((a) << (b))
#define COMP_SHR(a, b) ((a) >> (b))
#define COMP_AND(a, b) ((a) && (b))
#define COMP_OR(a, b) ((a) || (b))
#define COMP_CHOOSE(c, a, b) ((c) ? (a) : (b))
#define COMP_REPEAT(x) ((x) + (x))
#define COMP_UNUSED(x) (17)
#define COMP_CAST_BOOL(x) ((_Bool)(x))
#define COMP_CAST_CHAR(x) ((char)(x))
#define COMP_CAST_SCHAR(x) ((signed char)(x))
#define COMP_CAST_UCHAR(x) ((unsigned char)(x))
#define COMP_CAST_SHORT(x) ((short)(x))
#define COMP_CAST_USHORT(x) ((unsigned short)(x))
#define COMP_CAST_INT(x) ((int)(x))
#define COMP_CAST_UINT(x) ((unsigned int)(x))
#define COMP_CAST_LONG(x) ((long)(x))
#define COMP_CAST_ULONG(x) ((unsigned long)(x))
#define COMP_CAST_LLONG(x) ((long long)(x))
#define COMP_CAST_ULLONG(x) ((unsigned long long)(x))
#define COMP_CAST_I128(x) ((__int128)(x))
#define COMP_CAST_U128(x) ((unsigned __int128)(x))
